/** @typedef {()=>number} Callback */
/** @template T
 * @param {T} n
 * @returns {T} */
function helper(n){return n;}
/** @type {Callback} */ const result=helper(()=>3);export const observed=[result.name,result()];

/** @typedef {{run:(n:number)=>number}} Options */
/** @param {Options} options
 * @returns {number} */
function helper(options){return options.run(3);}
/** @type {number} */ const result=helper({run:n=>n+1});export const observed=result;
